// Credential-free demo output. Replace this node with your lead source, website research,
// AI scoring/draft generation, and Google Sheets or CRM steps for a live workflow.
const target = 'Dental clinics in Texas';
const leads = [
  { company: 'Lone Star Dental Care', location: 'Austin, TX', website: 'https://lonestardental.com', fit: 'Good fit', score: 94, research: 'Family dentistry focused on comfortable visits for busy families.', draft: 'Hi Lone Star team — I noticed your focus on comfortable family visits. We help independent practices follow up on new patient inquiries. Would a short overview be useful?', approval_status: 'Needs review' },
  { company: 'Bright Oak Dentistry', location: 'Dallas, TX', website: 'https://brightoakdental.com', fit: 'Good fit', score: 91, research: 'General dentistry with online booking and a clear new-patient offer.', draft: 'Hi Bright Oak team — online booking is a thoughtful touch for new patients. We help practices turn more local interest into booked visits. Open to a quick look?', approval_status: 'Needs review' },
  { company: 'Cedar Park Family Dental', location: 'Cedar Park, TX', website: 'https://cedarparkfamilydental.com', fit: 'Maybe', score: 73, research: 'Broad family dentistry service menu; growth priorities need confirmation.', draft: 'Hi Cedar Park team — we help clinics keep new-patient follow-up organized so fewer inquiries go cold. Is improving that process on your radar?', approval_status: 'Needs review' }
];
return leads.map(lead => ({ json: { target, researched_at: new Date().toISOString(), ...lead } }));
